import{_ as e,c as t,o as r,ae as o}from"./chunks/framework.CHDT0Kbg.js";const p=JSON.parse('{"title":"常見問題排查","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/troubleshooting.md","filePath":"zh-TW/guide/troubleshooting.md","lastUpdated":1795170900000}'),i={name:"zh-TW/guide/troubleshooting.md"};function l(h,a,n,s,d,u){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="常見問題排查" tabindex="-1">常見問題排查 <a class="header-anchor" href="#常見問題排查" aria-label="Permalink to &quot;常見問題排查&quot;">​</a></h1><p>遇到問題時可以試試這些辦法。</p><h2 id="網頁打不開" tabindex="-1">網頁打不開 <a class="header-anchor" href="#網頁打不開" aria-label="Permalink to &quot;網頁打不開&quot;">​</a></h2><ul><li>先確認其他網站能否開啟，再按 ⌘R 重新整理。</li><li>如果開啟了廣告攔截規則，先暫停一下，看看是不是攔了這個網站。</li><li>用無痕視窗（⌘⇧N）試試。如果無痕下正常，可在設定裡清除該網站的 Cookie。</li></ul><h2 id="下載卡住或不完整" tabindex="-1">下載卡住或不完整 <a class="header-anchor" href="#下載卡住或不完整" aria-label="Permalink to &quot;下載卡住或不完整&quot;">​</a></h2><ul><li>開啟下載面板，暫停後重試。</li><li>從網頁儲存的影片如果失敗，先刪除不完整的檔案再試。分段影片會合成一個 MP4，合成失敗時原始分片會留在下載目錄。</li></ul><h2 id="書籤沒匯入成功" tabindex="-1">書籤沒匯入成功 <a class="header-anchor" href="#書籤沒匯入成功" aria-label="Permalink to &quot;書籤沒匯入成功&quot;">​</a></h2><p>先在舊瀏覽器裡把書籤匯出成 HTML 檔，再在 Persim 的書籤管理員裡選擇「匯入 HTML」。資料夾和重複連結會自動處理。</p><h2 id="偵測不到影片" tabindex="-1">偵測不到影片 <a class="header-anchor" href="#偵測不到影片" aria-label="Permalink to &quot;偵測不到影片&quot;">​</a></h2><p>不是每個網站都能直接儲存影片。在目標頁面開啟媒體面板看看；如果沒有列出，代表該站點的播放方式不支援直接儲存。</p><h2 id="瀏覽器變慢" tabindex="-1">瀏覽器變慢 <a class="header-anchor" href="#瀏覽器變慢" aria-label="Permalink to &quot;瀏覽器變慢&quot;">​</a></h2><p>關掉不用的分頁，或停用不再需要的廣告攔截訂閱。網站權限可以在設定裡檢視。</p><h2 id="還是解決不了" tabindex="-1">還是解決不了 <a class="header-anchor" href="#還是解決不了" aria-label="Permalink to &quot;還是解決不了&quot;">​</a></h2><p>寄信到 <strong><a href="mailto:persim@w3cub.com" target="_blank" rel="noreferrer">persim@w3cub.com</a></strong>，說明你在做什麼，最好附上一張截圖。</p>',14)])])}const m=e(i,[["render",l]]);export{p as __pageData,m as default};
